params.command:
$ErrorActionPreference='Stop'
$repo='C:\Users\Xxkan\local-ai-workspaces\mhw-mods'
$wt='C:\Users\Xxkan\agent-worktrees\verify-pr156-updater-closure'
$expected='d9ca6aff0b26ce4cc21bd794bd500d0fce8c7ad4'
git -C $repo fetch origin --prune
$actual=(git -C $repo rev-parse origin/fix/updater-bom-release-closure-20260929).Trim()
if($actual -ne $expected){throw "PR156 head moved expected=$expected actual=$actual"}
if(Test-Path $wt){ git -C $repo worktree remove --force $wt 2>$null; Remove-Item -Recurse -Force $wt -ErrorAction SilentlyContinue }
git -C $repo worktree add --detach $wt $expected
try {
  git -C $wt diff --check "$((git -C $wt merge-base origin/main HEAD).Trim())..HEAD"
  if($LASTEXITCODE -ne 0){throw 'git diff --check failed'}
  dotnet restore "$wt\tests\MhwModManager.IntegrationTests\MhwModManager.IntegrationTests.csproj" -p:NuGetAudit=false
  if($LASTEXITCODE -ne 0){throw 'restore failed'}
  dotnet build "$wt\tests\MhwModManager.IntegrationTests\MhwModManager.IntegrationTests.csproj" -c Release --no-restore -p:NuGetAudit=false
  if($LASTEXITCODE -ne 0){throw 'build failed'}
  $runner="$wt\tests\MhwModManager.IntegrationTests\bin\Release\net10.0-windows10.0.19041.0\MhwModManager.IntegrationTests.exe"
  & $runner --filter-class "MhwModManager.IntegrationTests.UpdaterGitHubAssetDownloadTests"
  if($LASTEXITCODE -ne 0){throw 'UpdaterGitHubAssetDownloadTests failed'}
  $env:MHW_RUN_UPDATER_INSTALLED_E2E='0'
  & $runner --filter-class "MhwModManager.IntegrationTests.UpdaterInstalledClientE2ETests"
  if($LASTEXITCODE -ne 0){throw 'UpdaterInstalledClientE2ETests disabled-path failed'}
  Write-Host "VERIFIED_SHA=$expected"
  Write-Host "BUILD=PASS"
  Write-Host "FOCUSED_TESTS=PASS"
} finally {
  git -C $repo worktree remove --force $wt 2>$null
}
